use super::*;

/// The thresholds are JUDGEMENTS, named so they can be argued with rather than reverse-engineered.
pub fn stability_of(consistency: f64) -> Stability {
    if consistency >= 0.9 {
        Stability::Steady
    } else if consistency >= 0.6 {
        Stability::Variable
    } else {
        Stability::Lumpy
    }
}
